<?php
namespace App\Http\Middleware;
use App\Models\Device; use App\Support\ApiResponse; use Closure; use Illuminate\Http\Request; use Symfony\Component\HttpFoundation\Response;
class DeviceRequired { public function handle(Request $request, Closure $next): Response { $user=$request->user(); $du=$request->header('X-Device-UUID'); $iu=$request->header('X-Installation-UUID'); if(!$user||!$du||!$iu)return ApiResponse::error('Device headers are required.',422,null,'DEVICE_HEADERS_REQUIRED'); $device=Device::where('tenant_id',$user->tenant_id)->where('user_id',$user->id)->where('device_uuid',$du)->where('installation_uuid',$iu)->first(); if(!$device)return ApiResponse::error('This device is not registered.',403,null,'DEVICE_NOT_REGISTERED'); if(!$device->is_active||$device->revoked_at)return ApiResponse::error('This device has been revoked.',403,null,'DEVICE_REVOKED'); $device->forceFill(['last_seen_at'=>now()])->saveQuietly(); $request->attributes->set('device',$device); return $next($request); } }
